mapper.select:
SELECT id,run_id,attempt,node_id,request_key_hash,request_hash,question_bytes,answer_bytes FROM (
  SELECT h.id,h.run_id,h.attempt,h.node_id,h.request_key_hash,h.request_hash,h.create_time,
    OCTET_LENGTH(h.question_json) AS question_bytes,OCTET_LENGTH(h.answer_json) AS answer_bytes,
    ROW_NUMBER() OVER(PARTITION BY h.node_id ORDER BY h.create_time DESC,h.id DESC) AS node_position
  FROM paiflow_node_history h INNER JOIN paiflow_run_context c ON c.run_id=h.run_id
  WHERE c.space_id=#{space} AND c.workflow_id=#{workflow} AND c.owner_user_id=#{owner}
    AND c.app_id=#{app} AND c.chat_id=#{chat}
    AND h.node_id IN #{node}
) scoped WHERE node_position<=10 ORDER BY create_time DESC,id DESC LIMIT 1001

SELECT COALESCE(OCTET_LENGTH(r.assignment_json),0)+COALESCE((SELECT SUM(OCTET_LENGTH(e.event_json)) FROM paiflow_run_event e WHERE e.run_id=r.id),0)
  +COALESCE((SELECT SUM(OCTET_LENGTH(s.snapshot_json)) FROM paiflow_python_history_snapshot s WHERE s.run_id=r.id),0) AS bytes,
  (SELECT COUNT(*) FROM paiflow_run_event e WHERE e.run_id=r.id) AS row_count FROM paiflow_run r WHERE r.id=#{run}

SELECT id,nodeId,questionJson,answerJson FROM (
  SELECT h.id,h.node_id AS nodeId,h.question_json AS questionJson,h.answer_json AS answerJson,
    ROW_NUMBER() OVER(PARTITION BY h.node_id ORDER BY h.id DESC) AS nodePosition
  FROM paiflow_node_history h INNER JOIN paiflow_run_context c ON c.run_id=h.run_id
  WHERE c.space_id=#{space} AND c.workflow_id=#{workflow} AND c.owner_user_id=#{owner}
    AND c.app_id=#{app} AND c.chat_id=#{chat}
    AND h.node_id IN #{node}
) scoped WHERE nodePosition<=10 ORDER BY id DESC LIMIT 1001

SELECT h.* FROM paiflow_java_node_history h INNER JOIN paiflow_run_context c ON c.run_id=h.run_id
WHERE c.space_id=#{space} AND c.workflow_id=#{workflow} AND c.owner_user_id=#{owner}
  AND c.app_id=#{app} AND c.chat_id=#{chat} AND h.node_id=#{node}
ORDER BY h.id DESC LIMIT 10

mapper.update:
UPDATE paiflow_java_node_history SET item_json=#{item},item_hash=#{itemHash},model_operation_id=#{operation},
  state='COMPLETED',revision=revision+1
WHERE run_id=#{run} AND attempt=#{attempt} AND node_id=#{node} AND state='OPEN' AND revision=#{revision}
